                    if (uProgress > 0.0) {
                        // cut
                        vec2 uvTex = vUv - 0.5;
                        uvTex.x *= aspect;
                        uvTex += 0.5;
                        vec3 scrollTex = texture2D(tScroll, uvTex * 1.0).rgb;

